"""Berth planning arm — writes a shared-network compose plan for `kraken up`.

The `up` action renders a compose file that places every service on the
`kraken` network and writes it to the arm's data dir so `kraken up` can
read it without `--file`.
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

from kraken.core.paths import data_root, ensure_user_layout


COMPOSE = """\
# generated by berth — do not put secrets here
services:
  panel:
    image: nginx:alpine
    networks:
      - kraken
    ports:
      - "18181:80"
networks:
  kraken:
    name: kraken
    driver: bridge
"""


def _home(payload: dict[str, Any] | None) -> Path:
    body = payload or {}
    home = body.get("home") or os.environ.get("KRAKEN_HOME")
    return Path(home) if home else Path.home()


def handle(action: str, payload: dict[str, Any] | None = None, manifest=None) -> dict:
    body = payload or {}
    home = _home(body)
    ensure_user_layout(home)
    arm_dir = data_root(home) / "berth"
    arm_dir.mkdir(parents=True, exist_ok=True)

    if action == "up":
        (arm_dir / "compose.yaml").write_text(COMPOSE, encoding="utf-8")
        (arm_dir / "project.json").write_text(
            json.dumps({"name": "kraken"}), encoding="utf-8"
        )
        return {
            "ok": True,
            "arm": "berth",
            "action": "up",
            "plan": str(arm_dir / "compose.yaml"),
            "network": "kraken",
            "services": ["panel"],
        }

    if action == "plan":
        compose = arm_dir / "compose.yaml"
        return {
            "ok": compose.is_file(),
            "arm": "berth",
            "action": "plan",
            "plan": str(compose) if compose.is_file() else None,
            "exists": compose.is_file(),
        }

    return {"ok": True, "arm": "berth", "action": action}
